insert into REP_PROD_BONUS_REGISTER(ID, PROD_ID, BONUS_REGISTER_DATE, BONUS_DEALT_DATE, UNIT_BONUS_AMT, INPUT_TYPE, INPUT_USER, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select ID, PROD_ID, BONUS_REGISTER_DATE, BONUS_DEALT_DATE, UNIT_BONUS_AMT, INPUT_TYPE, INPUT_USER, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.id,jdbcType=CHAR} ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.bonusRegisterDate,jdbcType=DATE} BONUS_REGISTER_DATE, #{item.bonusDealtDate,jdbcType=DATE} BONUS_DEALT_DATE, #{item.unitBonusAmt,jdbcType=DECIMAL} UNIT_BONUS_AMT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} INPUT_USER, #{item.adapterId,jdbcType=VARCHAR} ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM dual
) TEMP where not exisits (select 1 from REP_PROD_BONUS_REGISTER CII where CII.PROD_ID = TEMP.PROD_ID AND CII.BONUS_REGISTER_DATE = TEMP.BONUS_REGISTER_DATE) ) de ;
UPDATE REP_PROD_BONUS_REGISTER as A, ( select ID, BONUS_DEALT_DATE, UNIT_BONUS_AMT, INPUT_TYPE, INPUT_USER, ADAPTER_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.id,jdbcType=CHAR} ID, #{item.prodId,jdbcType=VARCHAR} PROD_ID, #{item.bonusRegisterDate,jdbcType=DATE} BONUS_REGISTER_DATE, #{item.bonusDealtDate,jdbcType=DATE} BONUS_DEALT_DATE, #{item.unitBonusAmt,jdbcType=DECIMAL} UNIT_BONUS_AMT, #{item.inputType,jdbcType=VARCHAR} INPUT_TYPE, #{item.inputUser,jdbcType=VARCHAR} INPUT_USER, #{item.adapterId,jdbcType=VARCHAR} ADAPTER_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM dual
) TEMP ) de ) AS B set A.* = B.* where not exisits (select 1 from REP_PROD_BONUS_REGISTER CII where CII.PROD_ID = TEMP.PROD_ID AND CII.BONUS_REGISTER_DATE = TEMP.BONUS_REGISTER_DATE);
